                        pair_upper_m = next_expert_m == route_expert_m;
                    }
                } else {
                    owns_route_m = 0;
                }
            }
            unsigned int _phase_up_full = 0;
            if (owns_route_m) {
                unsigned int up_stage_mma = 0;
                #pragma unroll 1
                for (int kb_mma = 0; kb_mma < K / 256; kb_mma++) {
