inline void LaunchRetainedPortfolio(const TensorView& hidden_states, const TensorView& hidden_states_scale,
                   const TensorView& gemm1_weights, const TensorView& gemm1_weights_scale,
                   const TensorView& gemm2_weights, const TensorView& gemm2_weights_scale,
                   const TensorView& output1_scale_gate_scalar,
                   const TensorView& output1_scale_scalar, const TensorView& output2_scale_scalar,
                   const TensorView& sorted_token_ids, const TensorView& expert_ids,
                   const TensorView& num_tokens_post_padded, const TensorView& topk_weights,
                   const TensorView& accumulator, const ProblemDims& dims,
                   float routed_scaling_factor, cudaStream_t stream) {
  if (dims.m == 8 && dims.n == 1024 && dims.k == 6144 && gemm1_weights.size(0) == 256 && dims.top_k == 8 && dims.block_m == 8) {
    LaunchDecodeUp2Z2(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
        gemm2_weights, gemm2_weights_scale, output1_scale_gate_scalar,
        output1_scale_scalar, output2_scale_scalar, sorted_token_ids, expert_ids,
        num_tokens_post_padded, topk_weights, accumulator, dims, routed_scaling_factor, stream);
  }
  else if (dims.m == 128 && dims.n == 1024 && dims.k == 6144 && gemm1_weights.size(0) == 256 && dims.top_k == 8 && dims.block_m == 8) {
    LaunchBatchWordG2(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
        gemm2_weights, gemm2_weights_scale, output1_scale_gate_scalar,
        output1_scale_scalar, output2_scale_scalar, sorted_token_ids, expert_ids,
        num_tokens_post_padded, topk_weights, accumulator, dims, routed_scaling_factor, stream);
  }
  else if (dims.m == 512 && dims.n == 1024 && dims.k == 6144 && gemm1_weights.size(0) == 256 && dims.top_k == 8 && dims.block_m == 8) {
    LaunchBatchRetainedG8(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
        gemm2_weights, gemm2_weights_scale, output1_scale_gate_scalar,
        output1_scale_scalar, output2_scale_scalar, sorted_token_ids, expert_ids,
        num_tokens_post_padded, topk_weights, accumulator, dims, routed_scaling_factor, stream);
  }
  else {
    LaunchSmallRetained(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
        gemm2_weights, gemm2_weights_scale, output1_scale_gate_scalar,
        output1_scale_scalar, output2_scale_scalar, sorted_token_ids, expert_ids,
        num_tokens_post_padded, topk_weights, accumulator, dims, routed_scaling_factor, stream);
  }
}

// Optional immutable scale panels are supplied by model loading. Requests
// only inspect metadata and bind existing storage; raw scales remain inputs.
inline bool HasPreparedScale(const tvm::ffi::Optional<TensorView>& optional,
                             const TensorView& raw, int64_t panels, int rows) {
  if (!optional.has_value()) return false;
  const TensorView& value = optional.value();
  const DLDataType dtype = value.dtype();
  return dtype.code == kDLUInt && dtype.bits == 8 && dtype.lanes == 1 &&
      value.device().device_type == raw.device().device_type &&
      value.device().device_id == raw.device().device_id && value.ndim() == 3 &&
      value.IsContiguous() && value.size(0) == panels && value.size(1) == rows &&
      value.size(2) == 128 && reinterpret_cast<uintptr_t>(value.data_ptr()) % 16 == 0;
}

inline bool HasPreparedW2Data(const tvm::ffi::Optional<TensorView>& optional,
                              const TensorView& raw, int64_t panels) {
  // S12: prepare_nvfp4_w2_data panels [E*(K/128)*(N/256),128,64]: one contiguous 8 KB panel per
  // (expert, 128-row output tile, 128-wide intermediate block), the down kernels' TMA box.
  if (!optional.has_value()) return false;
  const TensorView& value = optional.value();
  const DLDataType dtype = value.dtype();
  return dtype.code == kDLUInt && dtype.bits == 8 && dtype.lanes == 1 &&
      value.device().device_type == raw.device().device_type &&
      value.device().device_id == raw.device().device_id && value.ndim() == 3 &&
      value.IsContiguous() && value.size(0) == panels && value.size(1) == 128 &&
      value.size(2) == 64 && reinterpret_cast<uintptr_t>(value.data_ptr()) % 16 == 0;
}

inline CUtensorMap EncodePreparedScaleTma(const TensorView& tensor, int rows) {
  uint64_t global_dim[3] = {128, static_cast<uint64_t>(rows),
                            static_cast<uint64_t>(tensor.size(0))};
  uint64_t global_strides[2] = {128, static_cast<uint64_t>(rows) * 128};
  uint32_t box_dim[3] = {128, static_cast<uint32_t>(rows), 1};
  uint32_t element_strides[3] = {1, 1, 1};
  CUtensorMap map;
  CheckCu(cuTensorMapEncodeTiled(
              &map, CU_TENSOR_MAP_DATA_TYPE_UINT8, 3, tensor.data_ptr(), global_dim,
              global_strides, box_dim, element_strides, CU_TENSOR_MAP_INTERLEAVE_NONE,
              CU_TENSOR_MAP_SWIZZLE_NONE, CU_TENSOR_MAP_L2_PROMOTION_NONE,
              CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE),
          "cuTensorMapEncodeTiled(prepared weight scales)");
  return map;
}

