inline CUtensorMap EncodeGateUpWeightsTma(const TensorView& tensor) {
  const uint64_t e = tensor.size(0), n = tensor.size(1), packed_k = tensor.size(2);
  uint64_t global_dim[5] = {128, 128, packed_k / 128, n / 256, 2 * e};
  uint64_t global_strides[4] = {packed_k, 128, 128 * packed_k, n * packed_k / 2};
  uint32_t box_dim[5] = {128, 128, 1, 1, 2};
  uint32_t element_strides[5] = {1, 1, 1, 1, 1};
  CUtensorMap map;
  CheckCu(cuTensorMapEncodeTiled(
      &map, CU_TENSOR_MAP_DATA_TYPE_UINT8, 5, tensor.data_ptr(), global_dim, global_strides,
      box_dim, element_strides, CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_128B,
      CU_TENSOR_MAP_L2_PROMOTION_NONE, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE),
      "cuTensorMapEncodeTiled(gate_up_weights)");
  return map;
}

inline CUtensorMap EncodeGateUpScaleTma(const TensorView& tensor, const ProblemDims& dims,
                                      int64_t experts) {
  const uint64_t blocks = dims.n / 256, tiles = dims.k / 256;
  uint64_t global_dim[5] = {128, 16, tiles, blocks, static_cast<uint64_t>(2 * experts)};
  uint64_t global_strides[4] = {128, 2048, tiles * 2048, blocks * tiles * 2048};
  uint32_t box_dim[5] = {128, 16, 1, 1, 2};
  uint32_t element_strides[5] = {1, 1, 1, 1, 1};
  CUtensorMap map;
  CheckCu(cuTensorMapEncodeTiled(
      &map, CU_TENSOR_MAP_DATA_TYPE_UINT8, 5, tensor.data_ptr(), global_dim, global_strides,
      box_dim, element_strides, CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_NONE,
      CU_TENSOR_MAP_L2_PROMOTION_NONE, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE),
      "cuTensorMapEncodeTiled(gate_up_scale)");
  return map;
}


inline void LaunchRank5W1Data(const TensorView& hidden_states, const TensorView& hidden_states_scale,
                   const TensorView& gemm1_weights, const TensorView& gemm1_weights_scale,
                   const TensorView& gemm2_weights, const TensorView& gemm2_weights_scale,
                   const TensorView& output1_scale_gate_scalar,
                   const TensorView& output1_scale_scalar, const TensorView& output2_scale_scalar,
                   const TensorView& sorted_token_ids, const TensorView& expert_ids,
                   const TensorView& num_tokens_post_padded, const TensorView& topk_weights,
                   const TensorView& accumulator, const ProblemDims& dims,
                   float routed_scaling_factor, cudaStream_t stream, const tvm::ffi::Optional<TensorView>& w1_scale_prepared, const tvm::ffi::Optional<TensorView>& w2_scale_prepared) {
  const CUtensorMap hidden_states_map = EncodeHiddenStatesTma(hidden_states);
  const CUtensorMap gemm1_map = EncodeGemm1WeightsTma(gemm1_weights);
  const CUtensorMap gate_up_map = EncodeGateUpWeightsTma(gemm1_weights);
  const CUtensorMap gemm2_map = EncodeGemm2WeightsTma(gemm2_weights);
  const int64_t capacity = dims.num_route_blocks * (dims.block_m / kRouteSubtile);
  const int64_t blocks = dims.n / kRowsPerIntermediateBlock;
  auto act_workspace = alloc_tensor({capacity * blocks, 512}, dl_uint8, hidden_states.device());
  auto sf_workspace = alloc_tensor({capacity * blocks, 1024}, dl_uint8, hidden_states.device());
  const dim3 up_grid(static_cast<unsigned int>(capacity), static_cast<unsigned int>(blocks), 1);
  const dim3 down_grid(static_cast<unsigned int>(capacity), static_cast<unsigned int>(blocks), static_cast<unsigned int>(dims.k / 128 < 2 ? dims.k / 128 : 2));
  const bool packed_scale_loads =
      reinterpret_cast<uintptr_t>(hidden_states_scale.data_ptr()) % 4 == 0 &&
      reinterpret_cast<uintptr_t>(gemm1_weights_scale.data_ptr()) % 4 == 0 &&
      reinterpret_cast<uintptr_t>(gemm2_weights_scale.data_ptr()) % 4 == 0;
  if (packed_scale_loads) {
    CheckCuda(SetMaxDynamicSmemOnce(nvfp4_decode_rank5_w1_data_up_word::kernel_alpha_moe_nvfp4_up_workspace_nvfp4_decode_rank5_w1_data_up_word, nvfp4_decode_rank5_w1_data_up_word::kGeneratedSmemTotal), "cudaFuncSetAttribute(alphamoe_nvfp4 up)");
    nvfp4_decode_rank5_w1_data_up_word::kernel_alpha_moe_nvfp4_up_workspace_nvfp4_decode_rank5_w1_data_up_word<<<up_grid, dim3(nvfp4_decode_rank5_w1_data_up_word::kGeneratedThreads, 1, 1),
        nvfp4_decode_rank5_w1_data_up_word::kGeneratedSmemTotal, stream>>>(
        hidden_states_map,
        gate_up_map,
        static_cast<uint8_t*>(hidden_states_scale.data_ptr()),
        static_cast<uint8_t*>(gemm1_weights_scale.data_ptr()),
        static_cast<float*>(output1_scale_gate_scalar.data_ptr()),
        static_cast<float*>(output1_scale_scalar.data_ptr()),
        static_cast<int*>(sorted_token_ids.data_ptr()),
        static_cast<int*>(expert_ids.data_ptr()),
        static_cast<int*>(num_tokens_post_padded.data_ptr()),
        static_cast<uint8_t*>(act_workspace.data_ptr()),
        static_cast<uint8_t*>(sf_workspace.data_ptr()),
        dims.m,
        dims.k,
        dims.top_k,
        dims.block_m);
    CheckCuda(cudaGetLastError(), "alphamoe_nvfp4 up launch");
    CheckCuda(SetMaxDynamicSmemOnce(nvfp4_decode_first_w2_down_word::kernel_alpha_moe_nvfp4_down_workspace_nvfp4_decode_first_w2_down_word, nvfp4_decode_first_w2_down_word::kGeneratedSmemTotal), "cudaFuncSetAttribute(alphamoe_nvfp4 down)");
    nvfp4_decode_first_w2_down_word::kernel_alpha_moe_nvfp4_down_workspace_nvfp4_decode_first_w2_down_word<<<down_grid, dim3(nvfp4_decode_first_w2_down_word::kGeneratedThreads, 1, 1),
        nvfp4_decode_first_w2_down_word::kGeneratedSmemTotal, stream>>>(
        gemm2_map,
        static_cast<uint8_t*>(gemm2_weights_scale.data_ptr()),
        static_cast<float*>(output2_scale_scalar.data_ptr()),
        static_cast<int*>(sorted_token_ids.data_ptr()),
        static_cast<int*>(expert_ids.data_ptr()),
        static_cast<int*>(num_tokens_post_padded.data_ptr()),
        static_cast<float*>(topk_weights.data_ptr()),
        static_cast<float*>(accumulator.data_ptr()),
        static_cast<uint8_t*>(act_workspace.data_ptr()),
        static_cast<uint8_t*>(sf_workspace.data_ptr()),
        dims.m,
        dims.k,
        dims.top_k,
        dims.block_m,
        routed_scaling_factor);
    CheckCuda(cudaGetLastError(), "alphamoe_nvfp4 down launch");
  }
  else {
    CheckCuda(SetMaxDynamicSmemOnce(nvfp4_decode_up2_byte_up::kernel_alpha_moe_nvfp4_up_workspace_nvfp4_decode_up2_byte_up, nvfp4_decode_up2_byte_up::kGeneratedSmemTotal), "cudaFuncSetAttribute(alphamoe_nvfp4 up)");
    nvfp4_decode_up2_byte_up::kernel_alpha_moe_nvfp4_up_workspace_nvfp4_decode_up2_byte_up<<<up_grid, dim3(nvfp4_decode_up2_byte_up::kGeneratedThreads, 1, 1),
        nvfp4_decode_up2_byte_up::kGeneratedSmemTotal, stream>>>(
        hidden_states_map,
        gemm1_map,
        static_cast<uint8_t*>(hidden_states_scale.data_ptr()),
        static_cast<uint8_t*>(gemm1_weights_scale.data_ptr()),
        static_cast<float*>(output1_scale_gate_scalar.data_ptr()),
        static_cast<float*>(output1_scale_scalar.data_ptr()),
        static_cast<int*>(sorted_token_ids.data_ptr()),
        static_cast<int*>(expert_ids.data_ptr()),
        static_cast<int*>(num_tokens_post_padded.data_ptr()),
        static_cast<uint8_t*>(act_workspace.data_ptr()),
        static_cast<uint8_t*>(sf_workspace.data_ptr()),
        dims.m,
        dims.k,
        dims.top_k,
        dims.block_m);
    CheckCuda(cudaGetLastError(), "alphamoe_nvfp4 up launch");
    CheckCuda(SetMaxDynamicSmemOnce(nvfp4_fallback_scale_byte_down::kernel_alpha_moe_nvfp4_down_workspace_byte, nvfp4_fallback_scale_byte_down::kGeneratedSmemTotal), "cudaFuncSetAttribute(alphamoe_nvfp4 down)");
    nvfp4_fallback_scale_byte_down::kernel_alpha_moe_nvfp4_down_workspace_byte<<<down_grid, dim3(nvfp4_fallback_scale_byte_down::kGeneratedThreads, 1, 1),
        nvfp4_fallback_scale_byte_down::kGeneratedSmemTotal, stream>>>(
        gemm2_map,
        static_cast<uint8_t*>(gemm2_weights_scale.data_ptr()),
        static_cast<float*>(output2_scale_scalar.data_ptr()),
        static_cast<int*>(sorted_token_ids.data_ptr()),
        static_cast<int*>(expert_ids.data_ptr()),
        static_cast<int*>(num_tokens_post_padded.data_ptr()),
        static_cast<float*>(topk_weights.data_ptr()),
        static_cast<float*>(accumulator.data_ptr()),
        static_cast<uint8_t*>(act_workspace.data_ptr()),
        static_cast<uint8_t*>(sf_workspace.data_ptr()),
        dims.m,
        dims.k,
        dims.top_k,
        dims.block_m,
        routed_scaling_factor);
    CheckCuda(cudaGetLastError(), "alphamoe_nvfp4 down launch");
  }
}

inline void LaunchRank5GateUp(const TensorView& hidden_states, const TensorView& hidden_states_scale,
                   const TensorView& gemm1_weights, const TensorView& gemm1_weights_scale,
                   const TensorView& gemm2_weights, const TensorView& gemm2_weights_scale,
                   const TensorView& output1_scale_gate_scalar,
                   const TensorView& output1_scale_scalar, const TensorView& output2_scale_scalar,
                   const TensorView& sorted_token_ids, const TensorView& expert_ids,
                   const TensorView& num_tokens_post_padded, const TensorView& topk_weights,
                   const TensorView& accumulator, const ProblemDims& dims,
                   float routed_scaling_factor, cudaStream_t stream, const tvm::ffi::Optional<TensorView>& w1_scale_prepared, const tvm::ffi::Optional<TensorView>& w2_scale_prepared) {
  const CUtensorMap hidden_states_map = EncodeHiddenStatesTma(hidden_states);
  const CUtensorMap gemm1_map = EncodeGemm1WeightsTma(gemm1_weights);
  const CUtensorMap gate_up_map = EncodeGateUpWeightsTma(gemm1_weights);
  const CUtensorMap gemm2_map = EncodeGemm2WeightsTma(gemm2_weights);
  const CUtensorMap w1_scale_map = EncodeGateUpScaleTma(w1_scale_prepared.value(), dims, gemm1_weights.size(0));
  const int64_t capacity = dims.num_route_blocks * (dims.block_m / kRouteSubtile);
  const int64_t blocks = dims.n / kRowsPerIntermediateBlock;
  auto act_workspace = alloc_tensor({capacity * blocks, 1024}, dl_uint8, hidden_states.device());
  auto sf_workspace = alloc_tensor({capacity * blocks, 1024}, dl_uint8, hidden_states.device());
  const dim3 up_grid(static_cast<unsigned int>(capacity), static_cast<unsigned int>(blocks), 1);
  const dim3 down_grid(static_cast<unsigned int>(capacity), static_cast<unsigned int>((blocks + 1) / 2), 1);
  const bool packed_scale_loads =
      reinterpret_cast<uintptr_t>(hidden_states_scale.data_ptr()) % 4 == 0 &&
      reinterpret_cast<uintptr_t>(gemm1_weights_scale.data_ptr()) % 4 == 0 &&
      reinterpret_cast<uintptr_t>(gemm2_weights_scale.data_ptr()) % 4 == 0;
  if (packed_scale_loads) {
    CheckCuda(SetMaxDynamicSmemOnce(nvfp4_batch_rank5_gate_up_word::kernel_alpha_moe_nvfp4_up_workspace_nvfp4_batch_rank5_gate_up_word, nvfp4_batch_rank5_gate_up_word::kGeneratedSmemTotal), "cudaFuncSetAttribute(alphamoe_nvfp4 up)");
    nvfp4_batch_rank5_gate_up_word::kernel_alpha_moe_nvfp4_up_workspace_nvfp4_batch_rank5_gate_up_word<<<up_grid, dim3(nvfp4_batch_rank5_gate_up_word::kGeneratedThreads, 1, 1),
        nvfp4_batch_rank5_gate_up_word::kGeneratedSmemTotal, stream>>>(
        hidden_states_map,
        gate_up_map,
        static_cast<uint8_t*>(hidden_states_scale.data_ptr()),
        w1_scale_map,
        static_cast<float*>(output1_scale_gate_scalar.data_ptr()),
        static_cast<float*>(output1_scale_scalar.data_ptr()),
        static_cast<int*>(sorted_token_ids.data_ptr()),
        static_cast<int*>(expert_ids.data_ptr()),
        static_cast<int*>(num_tokens_post_padded.data_ptr()),
        static_cast<uint8_t*>(act_workspace.data_ptr()),
        static_cast<uint8_t*>(sf_workspace.data_ptr()),
        dims.m,
        dims.k,
        dims.top_k,
        dims.block_m);
    CheckCuda(cudaGetLastError(), "alphamoe_nvfp4 up launch");
    CheckCuda(SetMaxDynamicSmemOnce(nvfp4_batch_first_w2_down_word::kernel_alpha_moe_nvfp4_down_workspace_nvfp4_batch_first_w2_down_word, nvfp4_batch_first_w2_down_word::kGeneratedSmemTotal), "cudaFuncSetAttribute(alphamoe_nvfp4 down)");
    nvfp4_batch_first_w2_down_word::kernel_alpha_moe_nvfp4_down_workspace_nvfp4_batch_first_w2_down_word<<<down_grid, dim3(nvfp4_batch_first_w2_down_word::kGeneratedThreads, 1, 1),
        nvfp4_batch_first_w2_down_word::kGeneratedSmemTotal, stream>>>(
        gemm2_map,
        static_cast<uint8_t*>(gemm2_weights_scale.data_ptr()),
        static_cast<float*>(output2_scale_scalar.data_ptr()),
        static_cast<int*>(sorted_token_ids.data_ptr()),
        static_cast<int*>(expert_ids.data_ptr()),
        static_cast<int*>(num_tokens_post_padded.data_ptr()),
        static_cast<float*>(topk_weights.data_ptr()),
        static_cast<float*>(accumulator.data_ptr()),
        static_cast<uint8_t*>(act_workspace.data_ptr()),
        static_cast<uint8_t*>(sf_workspace.data_ptr()),
        dims.m,
        dims.k,
        dims.top_k,
        dims.block_m,
        routed_scaling_factor,
        static_cast<int>(blocks));
    CheckCuda(cudaGetLastError(), "alphamoe_nvfp4 down launch");
  }
  else {
    CheckCuda(SetMaxDynamicSmemOnce(nvfp4_batch_word_g2_byte_up::kernel_alpha_moe_nvfp4_up_workspace_nvfp4_batch_word_g2_byte_up, nvfp4_batch_word_g2_byte_up::kGeneratedSmemTotal), "cudaFuncSetAttribute(alphamoe_nvfp4 up)");
    nvfp4_batch_word_g2_byte_up::kernel_alpha_moe_nvfp4_up_workspace_nvfp4_batch_word_g2_byte_up<<<up_grid, dim3(nvfp4_batch_word_g2_byte_up::kGeneratedThreads, 1, 1),
        nvfp4_batch_word_g2_byte_up::kGeneratedSmemTotal, stream>>>(
        hidden_states_map,
        gemm1_map,
        static_cast<uint8_t*>(hidden_states_scale.data_ptr()),
        static_cast<uint8_t*>(gemm1_weights_scale.data_ptr()),
        static_cast<float*>(output1_scale_gate_scalar.data_ptr()),
        static_cast<float*>(output1_scale_scalar.data_ptr()),
        static_cast<int*>(sorted_token_ids.data_ptr()),
        static_cast<int*>(expert_ids.data_ptr()),
        static_cast<int*>(num_tokens_post_padded.data_ptr()),
        static_cast<uint8_t*>(act_workspace.data_ptr()),
        static_cast<uint8_t*>(sf_workspace.data_ptr()),
        dims.m,
        dims.k,
        dims.top_k,
        dims.block_m);
    CheckCuda(cudaGetLastError(), "alphamoe_nvfp4 up launch");
    CheckCuda(SetMaxDynamicSmemOnce(nvfp4_batch_word_g2_byte_down::kernel_alpha_moe_nvfp4_down_workspace_nvfp4_batch_word_g2_byte_down, nvfp4_batch_word_g2_byte_down::kGeneratedSmemTotal), "cudaFuncSetAttribute(alphamoe_nvfp4 down)");
    nvfp4_batch_word_g2_byte_down::kernel_alpha_moe_nvfp4_down_workspace_nvfp4_batch_word_g2_byte_down<<<down_grid, dim3(nvfp4_batch_word_g2_byte_down::kGeneratedThreads, 1, 1),
        nvfp4_batch_word_g2_byte_down::kGeneratedSmemTotal, stream>>>(
        gemm2_map,
        static_cast<uint8_t*>(gemm2_weights_scale.data_ptr()),
        static_cast<float*>(output2_scale_scalar.data_ptr()),
        static_cast<int*>(sorted_token_ids.data_ptr()),
        static_cast<int*>(expert_ids.data_ptr()),
        static_cast<int*>(num_tokens_post_padded.data_ptr()),
        static_cast<float*>(topk_weights.data_ptr()),
        static_cast<float*>(accumulator.data_ptr()),
        static_cast<uint8_t*>(act_workspace.data_ptr()),
        static_cast<uint8_t*>(sf_workspace.data_ptr()),
        dims.m,
        dims.k,
        dims.top_k,
        dims.block_m,
        routed_scaling_factor,
        static_cast<int>(blocks));
    CheckCuda(cudaGetLastError(), "alphamoe_nvfp4 down launch");
  }
}

inline void LaunchCurrent(const TensorView& hidden_states, const TensorView& hidden_states_scale,
                   const TensorView& gemm1_weights, const TensorView& gemm1_weights_scale,
                   const TensorView& gemm2_weights, const TensorView& gemm2_weights_scale,
                   const TensorView& output1_scale_gate_scalar,
                   const TensorView& output1_scale_scalar, const TensorView& output2_scale_scalar,
                   const TensorView& sorted_token_ids, const TensorView& expert_ids,
                   const TensorView& num_tokens_post_padded, const TensorView& topk_weights,
                   const TensorView& accumulator, const ProblemDims& dims,
                   float routed_scaling_factor, cudaStream_t stream, const tvm::ffi::Optional<TensorView>& w1_scale_prepared, const tvm::ffi::Optional<TensorView>& w2_scale_prepared) {
  const bool packed_scale_loads =
      reinterpret_cast<uintptr_t>(hidden_states_scale.data_ptr()) % 4 == 0 &&
      reinterpret_cast<uintptr_t>(gemm1_weights_scale.data_ptr()) % 4 == 0 &&
      reinterpret_cast<uintptr_t>(gemm2_weights_scale.data_ptr()) % 4 == 0;
  const bool prepared_w1 = packed_scale_loads && HasPreparedScale(
      w1_scale_prepared, gemm1_weights_scale,
      gemm1_weights.size(0) * (dims.n / 128) * (dims.k / 256), 16);
  const bool prepared_w2 = packed_scale_loads &&
      reinterpret_cast<uintptr_t>(gemm2_weights_scale.data_ptr()) % 8 == 0 && HasPreparedScale(
          w2_scale_prepared, gemm2_weights_scale,
          gemm1_weights.size(0) * (dims.k / 128) * (dims.n / 256), 8);
  if (dims.m == 1 && dims.n == 1024 && dims.k == 6144 &&
      gemm1_weights.size(0) == 256 && dims.top_k == 8 && dims.block_m == 8) {
    LaunchFirstW2M1(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
        gemm2_weights, gemm2_weights_scale, output1_scale_gate_scalar,
        output1_scale_scalar, output2_scale_scalar, sorted_token_ids, expert_ids,
        num_tokens_post_padded, topk_weights, accumulator, dims, routed_scaling_factor, stream);
    return;
  }
  if (dims.m == 8 && dims.n == 1024 && dims.k == 6144 && gemm1_weights.size(0) == 256 && dims.top_k == 8 && dims.block_m == 8) {
    LaunchRank5W1Data(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
        gemm2_weights, gemm2_weights_scale, output1_scale_gate_scalar,
        output1_scale_scalar, output2_scale_scalar, sorted_token_ids, expert_ids,
        num_tokens_post_padded, topk_weights, accumulator, dims, routed_scaling_factor, stream, w1_scale_prepared, w2_scale_prepared);
  }
  else if (dims.m == 128 && dims.n == 1024 && dims.k == 6144 && gemm1_weights.size(0) == 256 && dims.top_k == 8 && dims.block_m == 8 && prepared_w1) {
    LaunchRank5GateUp(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
        gemm2_weights, gemm2_weights_scale, output1_scale_gate_scalar,
        output1_scale_scalar, output2_scale_scalar, sorted_token_ids, expert_ids,
        num_tokens_post_padded, topk_weights, accumulator, dims, routed_scaling_factor, stream, w1_scale_prepared, w2_scale_prepared);
  }
  else if (dims.m == 512 && dims.n == 1024 && dims.k == 6144 && gemm1_weights.size(0) == 256 && dims.top_k == 8 && dims.block_m == 8 && prepared_w1 && prepared_w2) {
    LaunchBatchPreparedG8(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
        gemm2_weights, gemm2_weights_scale, output1_scale_gate_scalar,
        output1_scale_scalar, output2_scale_scalar, sorted_token_ids, expert_ids,
        num_tokens_post_padded, topk_weights, accumulator, dims, routed_scaling_factor, stream, w1_scale_prepared, w2_scale_prepared);
  }
  else if (dims.m == 512 && dims.n == 1024 && dims.k == 6144 && gemm1_weights.size(0) == 256 && dims.top_k == 8 && dims.block_m == 8 && prepared_w1) {
    LaunchBatchPreparedW1G8(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
        gemm2_weights, gemm2_weights_scale, output1_scale_gate_scalar,
        output1_scale_scalar, output2_scale_scalar, sorted_token_ids, expert_ids,
        num_tokens_post_padded, topk_weights, accumulator, dims, routed_scaling_factor, stream, w1_scale_prepared, w2_scale_prepared);
  }
  else {
    LaunchRetainedPortfolio(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
        gemm2_weights, gemm2_weights_scale, output1_scale_gate_scalar,
        output1_scale_scalar, output2_scale_scalar, sorted_token_ids, expert_ids,
        num_tokens_post_padded, topk_weights, accumulator, dims, routed_scaling_factor, stream);
  }
}

void RunCurrent(TensorView hidden_states, TensorView hidden_states_scale, TensorView gemm1_weights,
         TensorView gemm1_weights_scale, TensorView gemm2_weights, TensorView gemm2_weights_scale,
         TensorView output1_scale_gate_scalar, TensorView output1_scale_scalar,
         TensorView output2_scale_scalar, TensorView sorted_token_ids, TensorView expert_ids,
         TensorView num_tokens_post_padded, TensorView topk_weights, TensorView out,
         TensorView accumulator, int64_t top_k, int64_t block_m, double routed_scaling_factor, tvm::ffi::Optional<TensorView> w1_scale_prepared, tvm::ffi::Optional<TensorView> w2_scale_prepared) {
  // Establish the active CUDA device before capability queries, TMA encoding,
  // function-attribute updates, stream lookup, or kernel launch.
  TVM_FFI_ICHECK(hidden_states.device().device_type == kDLCUDA)
      << "hidden_states must be a CUDA tensor";
  ffi::CUDADeviceGuard device_guard(hidden_states.device().device_id);

  const ProblemDims dims = CheckInputs(
      hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale, gemm2_weights,
      gemm2_weights_scale, output1_scale_gate_scalar, output1_scale_scalar, output2_scale_scalar,
      sorted_token_ids, expert_ids, num_tokens_post_padded, topk_weights, out, accumulator, top_k,
      block_m, routed_scaling_factor);
  const cudaStream_t stream = get_stream(hidden_states.device());
  LaunchCurrent(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale, gemm2_weights,
         gemm2_weights_scale, output1_scale_gate_scalar, output1_scale_scalar, output2_scale_scalar,
         sorted_token_ids, expert_ids, num_tokens_post_padded, topk_weights, accumulator, dims,
         static_cast<float>(routed_scaling_factor), stream, w1_scale_prepared, w2_scale_prepared);
}

void RunRoutedSeededCurrent(
    TensorView hidden_states, TensorView hidden_states_scale, TensorView gemm1_weights,
    TensorView gemm1_weights_scale, TensorView gemm2_weights, TensorView gemm2_weights_scale,
    TensorView output1_scale_gate_scalar, TensorView output1_scale_scalar,
    TensorView output2_scale_scalar, TensorView sorted_token_ids, TensorView expert_ids,
    TensorView num_tokens_post_padded, TensorView topk_weights, TensorView out,
    TensorView accumulator, TensorView topk_ids, TensorView cumsum_buffer,
    int64_t top_k, int64_t block_m, double routed_scaling_factor, tvm::ffi::Optional<TensorView> w1_scale_prepared, tvm::ffi::Optional<TensorView> w2_scale_prepared) {
  TVM_FFI_ICHECK(hidden_states.device().device_type == kDLCUDA)
      << "hidden_states must be a CUDA tensor";
  ffi::CUDADeviceGuard device_guard(hidden_states.device().device_id);
  // Preserve all existing aligned host checks before the first GPU launch.
  (void)CheckInputs(
      hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale, gemm2_weights,
      gemm2_weights_scale, output1_scale_gate_scalar, output1_scale_scalar, output2_scale_scalar,
      sorted_token_ids, expert_ids, num_tokens_post_padded, topk_weights, out, accumulator,
      top_k, block_m, routed_scaling_factor);
  CheckTensor(topk_ids, dl_int32, 2, true, "topk_ids", "int32");
  CheckSameDevice(topk_ids, hidden_states.device().device_id, "topk_ids");
  CheckShape2(topk_ids, hidden_states.size(0), top_k, "topk_ids");
  AlignAndSeedOutput(topk_ids, gemm1_weights.size(0) + 1, block_m,
                     sorted_token_ids, expert_ids, num_tokens_post_padded, cumsum_buffer,
                     out, accumulator, true);
  // The current aligned implementation consumes
  // exactly the accumulator initialized by the preceding same-stream launch.
  RunCurrent(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale, gemm2_weights,
      gemm2_weights_scale, output1_scale_gate_scalar, output1_scale_scalar, output2_scale_scalar,
      sorted_token_ids, expert_ids, num_tokens_post_padded, topk_weights, out, accumulator,
      top_k, block_m, routed_scaling_factor, w1_scale_prepared, w2_scale_prepared);
}

void RunRoutedSeededGeneralCurrent(
    TensorView hidden_states, TensorView hidden_states_scale, TensorView gemm1_weights,
    TensorView gemm1_weights_scale, TensorView gemm2_weights, TensorView gemm2_weights_scale,
    TensorView output1_scale_gate_scalar, TensorView output1_scale_scalar,
    TensorView output2_scale_scalar, TensorView sorted_token_ids, TensorView expert_ids,
    TensorView num_tokens_post_padded, TensorView topk_weights, TensorView out,
    TensorView accumulator, TensorView topk_ids, TensorView cumsum_buffer,
    int64_t top_k, int64_t block_m, double routed_scaling_factor, tvm::ffi::Optional<TensorView> w1_scale_prepared, tvm::ffi::Optional<TensorView> w2_scale_prepared) {
  TVM_FFI_ICHECK(hidden_states.device().device_type == kDLCUDA)
      << "hidden_states must be a CUDA tensor";
  ffi::CUDADeviceGuard device_guard(hidden_states.device().device_id);
  // Preserve all existing aligned host checks before the first GPU launch.
  (void)CheckInputs(
      hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale, gemm2_weights,
      gemm2_weights_scale, output1_scale_gate_scalar, output1_scale_scalar, output2_scale_scalar,
      sorted_token_ids, expert_ids, num_tokens_post_padded, topk_weights, out, accumulator,
      top_k, block_m, routed_scaling_factor);
  CheckTensor(topk_ids, dl_int32, 2, true, "topk_ids", "int32");
  CheckSameDevice(topk_ids, hidden_states.device().device_id, "topk_ids");
  CheckShape2(topk_ids, hidden_states.size(0), top_k, "topk_ids");
  AlignAndSeedOutputGeneral(topk_ids, gemm1_weights.size(0) + 1, block_m,
                     sorted_token_ids, expert_ids, num_tokens_post_padded, cumsum_buffer,
                     out, accumulator, true);
  // The current aligned implementation consumes
  // exactly the accumulator initialized by the preceding same-stream launch.
  RunCurrent(hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale, gemm2_weights,
      gemm2_weights_scale, output1_scale_gate_scalar, output1_scale_scalar, output2_scale_scalar,
      sorted_token_ids, expert_ids, num_tokens_post_padded, topk_weights, out, accumulator,
      top_k, block_m, routed_scaling_factor, w1_scale_prepared, w2_scale_prepared);
}
