                owner_warp_inclusive = owner_warp_inclusive + owner_warp_peer_3;
            }
            if (lane < 8) {
                warp_prefix[lane] = warp_inclusive - warp_total;
                owner_warp_prefix[lane] = owner_warp_inclusive - owner_warp_total;
            }
            if (lane == 7) {
