                                tma_3d_gmem2smem(smem_w1_addr + up_stage * 43008, (&W1), 0, 0, (expert * (2 * intermediate_blocks) + intermediate_block) * (K / 256) + kb, up_full_addr + (up_stage) * 8);
                            }
                        }
