                            int _mma_a_lo_0 = make_warp_uniform((((smem_w1_addr) >> 4) & 0x3FFF) + (up_stage_mma) * 2688);
                            int _mma_b_lo_0 = make_warp_uniform((((smem_x_wide_addr) >> 4) & 0x3FFF) + (up_stage_mma) * 2688);
                            if (elect_sync()) {
