    }
    // ---- Role: consumer ----
    if (warp >= 2 && warp <= 5) {
        { // consumer_main
            bool owns_route_c = blockIdx.x < compact_owner_count[0];
            int original_tile_c = 0;
            int route_base_c = 0;
            bool pair_upper_c = 0;
            bool has_second_c = 0;
            bool second_upper_c = 0;
            int route_expert_c = 0;
            if (owns_route_c) {
