                route_expert_c = compact_owner_plan[blockIdx.x * 3 + 1];
                int live_subtiles_c = compact_owner_plan[blockIdx.x * 3 + 2];
                pair_upper_c = live_subtiles_c >= 2;
                has_second_c = live_subtiles_c >= 3;
                second_upper_c = live_subtiles_c == 4;
            }
