  CheckNoOverlap(out, gemm1_weights_scale, "gemm1_weights_scale");
  CheckNoOverlap(out, gemm2_weights, "gemm2_weights");
  CheckNoOverlap(out, gemm2_weights_scale, "gemm2_weights_scale");
  CheckNoOverlap(out, output1_scale_gate_scalar, "output1_scale_gate_scalar");
  CheckNoOverlap(out, output1_scale_scalar, "output1_scale_scalar");
  CheckNoOverlap(out, output2_scale_scalar, "output2_scale_scalar");
  CheckNoOverlap(out, sorted_token_ids, "sorted_token_ids");
  CheckNoOverlap(out, expert_ids, "expert_ids");
  CheckNoOverlap(out, num_tokens_post_padded, "num_tokens_post_padded");
  CheckNoOverlap(out, topk_weights, "topk_weights");


  TVM_FFI_ICHECK(num_tokens_post_padded.numel() == 1)
      << "num_tokens_post_padded must contain exactly one device-side int32 value";
  const int64_t num_route_blocks = expert_ids.numel();
  TVM_FFI_ICHECK(num_route_blocks > 0) << "expert_ids must not be empty";
  TVM_FFI_ICHECK(num_route_blocks <= kIntMax / block_m)
      << "expert_ids.numel() * block_m exceeds signed int indexing";
  const int64_t required_plan_capacity = num_route_blocks * block_m;
  TVM_FFI_ICHECK(sorted_token_ids.numel() >= required_plan_capacity)
      << "sorted_token_ids capacity (" << sorted_token_ids.numel()
      << ") must be at least expert_ids.numel() * block_m (" << required_plan_capacity << ")";

  TVM_FFI_ICHECK(m <= kIntMax / top_k) << "M * top_k exceeds the signed int routing sentinel range";
  TVM_FFI_ICHECK(m <= kIntMax / k) << "M * K exceeds signed int indexing";
  CheckIntIndexExtent(m, "M");
  CheckIntIndexExtent(k, "K");
  CheckIntIndexExtent(m * k, "M * K output extent");
  CheckIntIndexExtent(hidden_states_scale.numel(), "hidden_states_scale.numel()");
  CheckIntIndexExtent(gemm1_weights_scale.numel(), "gemm1_weights_scale.numel()");
  CheckIntIndexExtent(gemm2_weights_scale.numel(), "gemm2_weights_scale.numel()");
  CheckIntIndexExtent(required_plan_capacity, "routing plan capacity");

  const int64_t grid_x = num_route_blocks * (block_m / kRouteSubtile);
  TVM_FFI_ICHECK(grid_x > 0 && grid_x <= kIntMax)
      << "launch grid.x (" << grid_x << ") is out of range";
  const int64_t grid_y = n / kRowsPerIntermediateBlock;
  TVM_FFI_ICHECK(grid_y > 0 && grid_y <= 65535)
      << "launch grid.y (" << grid_y << ") is out of range";

  return ProblemDims{static_cast<int>(m),     static_cast<int>(k),
                     static_cast<int>(n),     static_cast<int>(intermediate),
                     static_cast<int>(top_k), static_cast<int>(block_m),
                     num_route_blocks};
}

void RunCompleteSmallAlignment(
    TensorView hidden_states, TensorView hidden_states_scale, TensorView gemm1_weights,
    TensorView gemm1_weights_scale, TensorView gemm2_weights, TensorView gemm2_weights_scale,
    TensorView output1_scale_gate_scalar, TensorView output1_scale_scalar,
    TensorView output2_scale_scalar, TensorView sorted_token_ids, TensorView expert_ids,
    TensorView num_tokens_post_padded, TensorView topk_weights, TensorView out,
    TensorView topk_ids, TensorView cumsum_buffer,
    int64_t top_k, int64_t block_m, double routed_scaling_factor) {
  TVM_FFI_ICHECK(hidden_states.device().device_type == kDLCUDA)
      << "hidden_states must be a CUDA tensor";
  ffi::CUDADeviceGuard device_guard(hidden_states.device().device_id);
  const ProblemDims dims = CheckCompleteInputs(
      hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
      gemm2_weights, gemm2_weights_scale, output1_scale_gate_scalar, output1_scale_scalar,
      output2_scale_scalar, sorted_token_ids, expert_ids, num_tokens_post_padded,
      topk_weights, out, top_k, block_m, routed_scaling_factor);
  constexpr int64_t route_id = 8;

  TVM_FFI_ICHECK(route_id >= 1 && route_id <= 8) << "invalid complete route id";
  TVM_FFI_ICHECK(dims.n == 1024 && dims.k == 6144 && gemm1_weights.size(0) == 256 &&
                 dims.top_k == 8 && dims.block_m == 8)
      << "complete route requires its selected geometry";
  const int device_id = hidden_states.device().device_id;
  CheckTensor(topk_ids, dl_int32, 2, true, "topk_ids", "int32");
  CheckSameDevice(topk_ids, device_id, "topk_ids");
  CheckShape2(topk_ids, dims.m, dims.top_k, "topk_ids");
  CheckTensor(cumsum_buffer, dl_int32, 1, true, "cumsum_buffer", "int32");
  CheckSameDevice(cumsum_buffer, device_id, "cumsum_buffer");
  TVM_FFI_ICHECK(cumsum_buffer.numel() >= gemm1_weights.size(0) + 2)
      << "cumsum_buffer must include all expert bins and the final prefix";
  CheckNoOverlap(out, topk_ids, "topk_ids");
  CheckNoOverlap(out, cumsum_buffer, "cumsum_buffer");
  TVM_FFI_ICHECK(dims.m >= 2 && dims.m < 8)
      << "small complete alignment requires two to seven tokens";
  const cudaStream_t stream = get_stream(hidden_states.device());

    constexpr int num_experts = 257;
    constexpr int scan_size = 512;
    constexpr int alignment_threads = 1024;
    constexpr int alignment_smem = (num_experts + num_experts + 1 + scan_size + 32) * sizeof(int32_t);
    alphamoe_complete_small_alignment::moe_align_block_size_kernel<int32_t>
        <<<2, alignment_threads, alignment_smem, stream>>>(
        static_cast<const int32_t*>(topk_ids.data_ptr()),
        static_cast<int32_t*>(sorted_token_ids.data_ptr()),
        static_cast<int32_t*>(expert_ids.data_ptr()),
        static_cast<int32_t*>(num_tokens_post_padded.data_ptr()),
        num_experts, dims.block_m, topk_ids.numel(),
        static_cast<int32_t*>(cumsum_buffer.data_ptr()), true, false,
        scan_size, static_cast<int32_t>(sorted_token_ids.numel()));
    CheckCuda(cudaGetLastError(), "complete small alignment launch");
    const int sort_blocks = std::min<int64_t>((topk_ids.numel() + 255) / 256, 65535);
    alphamoe_complete_small_alignment::count_and_sort_expert_tokens_kernel<int32_t>
        <<<sort_blocks, 256, 0, stream>>>(
        static_cast<const int32_t*>(topk_ids.data_ptr()),
        static_cast<int32_t*>(sorted_token_ids.data_ptr()),
        static_cast<int32_t*>(cumsum_buffer.data_ptr()), topk_ids.numel(), false);
    CheckCuda(cudaGetLastError(), "complete small sort launch");
}

inline CUtensorMap EncodePreparedW1DataTma(const TensorView& tensor) {
  uint64_t global_dim[3] = {128, 128, static_cast<uint64_t>(tensor.size(0))};
  uint64_t global_strides[2] = {128, 16384};
  uint32_t box_dim[3] = {128, 128, 1};
  uint32_t element_strides[3] = {1, 1, 1};
  CUtensorMap map;
  CheckCu(cuTensorMapEncodeTiled(
              &map, CU_TENSOR_MAP_DATA_TYPE_UINT8, 3, tensor.data_ptr(), global_dim,
              global_strides, box_dim, element_strides, CU_TENSOR_MAP_INTERLEAVE_NONE,
              CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_NONE,
              CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE),
          "cuTensorMapEncodeTiled(prepared W1 data)");
  return map;
}

inline CUtensorMap EncodePreparedW2DataTma(const TensorView& tensor) {
  // S12: prepared W2 panels; a (64 B, 128 row) box is one contiguous 8 KB panel, 64B swizzle like the raw W2 map.
  uint64_t global_dim[3] = {64, 128, static_cast<uint64_t>(tensor.size(0))};
  uint64_t global_strides[2] = {64, 8192};
  uint32_t box_dim[3] = {64, 128, 1};
  uint32_t element_strides[3] = {1, 1, 1};
  CUtensorMap map;
  CheckCu(cuTensorMapEncodeTiled(
              &map, CU_TENSOR_MAP_DATA_TYPE_UINT8, 3, tensor.data_ptr(), global_dim,
              global_strides, box_dim, element_strides, CU_TENSOR_MAP_INTERLEAVE_NONE,
              CU_TENSOR_MAP_SWIZZLE_64B, CU_TENSOR_MAP_L2_PROMOTION_NONE,
              CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE),
          "cuTensorMapEncodeTiled(prepared W2 data)");
  return map;
}

// ---- S13: large-M token-tile route (route 16) helpers ----
inline bool IsPreparedPanels(const TensorView& value, const TensorView& raw, int64_t panels, int rows) {
  // Required (non-optional) prepared panel sidecar [panels, rows, 128] uint8 on the raw tensor's device: the
  // prepared W1 data (rows 128) / W1 scales (rows 16) panels and the K-256 W2 data (rows 128) / scale (rows 16)
  // panels of prepare_nvfp4_w2_data_k256 / prepare_nvfp4_w2_scales_k256.
  const DLDataType dtype = value.dtype();
  return dtype.code == kDLUInt && dtype.bits == 8 && dtype.lanes == 1 &&
      value.device().device_type == raw.device().device_type &&
      value.device().device_id == raw.device().device_id && value.ndim() == 3 &&
      value.IsContiguous() && value.size(0) == panels && value.size(1) == rows &&
      value.size(2) == 128 && reinterpret_cast<uintptr_t>(value.data_ptr()) % 16 == 0;
}

inline CUtensorMap EncodePreparedW2DataK256Tma(const TensorView& tensor) {
  // Same geometry as the prepared W1 panels: a (128 B, 128 row) box is one contiguous 16 KB panel, 128B swizzle.
  uint64_t global_dim[3] = {128, 128, static_cast<uint64_t>(tensor.size(0))};
  uint64_t global_strides[2] = {128, 16384};
  uint32_t box_dim[3] = {128, 128, 1};
  uint32_t element_strides[3] = {1, 1, 1};
  CUtensorMap map;
  CheckCu(cuTensorMapEncodeTiled(
              &map, CU_TENSOR_MAP_DATA_TYPE_UINT8, 3, tensor.data_ptr(), global_dim,
              global_strides, box_dim, element_strides, CU_TENSOR_MAP_INTERLEAVE_NONE,
              CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_NONE,
              CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE),
          "cuTensorMapEncodeTiled(prepared K-256 W2 data)");
  return map;
}

inline CUtensorMap EncodeTokenTileActTma(const TensorView& act, int64_t tiles, int64_t row_bytes) {
  // Token-major activation workspace [tiles, 128, blocks*64] (full 256 B FP4 rows per tile row); the down kernel
  // loads one (128 B, 128 row) box per 256-wide intermediate K chunk, 128B swizzle.
  uint64_t global_dim[3] = {static_cast<uint64_t>(row_bytes), 128, static_cast<uint64_t>(tiles)};
  uint64_t global_strides[2] = {static_cast<uint64_t>(row_bytes), static_cast<uint64_t>(128 * row_bytes)};
  uint32_t box_dim[3] = {128, 128, 1};
  uint32_t element_strides[3] = {1, 1, 1};
  CUtensorMap map;
  CheckCu(cuTensorMapEncodeTiled(
              &map, CU_TENSOR_MAP_DATA_TYPE_UINT8, 3, act.data_ptr(), global_dim,
              global_strides, box_dim, element_strides, CU_TENSOR_MAP_INTERLEAVE_NONE,
              CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_NONE,
              CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE),
          "cuTensorMapEncodeTiled(token-tile act workspace)");
  return map;
}

inline CUtensorMap EncodeTokenTileRouteAccTma(const TensorView& acc, int64_t tiles, int64_t k, uint32_t box_rows) {
  // Tile-major BF16 route accumulator viewed [tiles, 128, K]; the down kernel stores (64 BF16 = 128 B, box_rows) boxes
  // (32-row live panels, 8-row tails), 128B swizzle. Strides are bytes.
  uint64_t global_dim[3] = {static_cast<uint64_t>(k), 128, static_cast<uint64_t>(tiles)};
  uint64_t global_strides[2] = {static_cast<uint64_t>(k) * 2, static_cast<uint64_t>(k) * 256};
  uint32_t box_dim[3] = {64, box_rows, 1};
  uint32_t element_strides[3] = {1, 1, 1};
  CUtensorMap map;
  CheckCu(cuTensorMapEncodeTiled(
              &map, CU_TENSOR_MAP_DATA_TYPE_BFLOAT16, 3, acc.data_ptr(), global_dim,
              global_strides, box_dim, element_strides, CU_TENSOR_MAP_INTERLEAVE_NONE,
              CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_NONE,
              CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE),
          "cuTensorMapEncodeTiled(token-tile route accumulator)");
  return map;
}

inline CUtensorMap EncodePreparedW1DataHalfTma(const TensorView& tensor) {
  // S6: same prepare_nvfp4_w1_data panels, 64-row boxes (the M=8 up kernel loads one gate and one up half per stage).
  uint64_t global_dim[3] = {128, 128, static_cast<uint64_t>(tensor.size(0))};
  uint64_t global_strides[2] = {128, 16384};
  uint32_t box_dim[3] = {128, 64, 1};
  uint32_t element_strides[3] = {1, 1, 1};
  CUtensorMap map;
  CheckCu(cuTensorMapEncodeTiled(
              &map, CU_TENSOR_MAP_DATA_TYPE_UINT8, 3, tensor.data_ptr(), global_dim,
              global_strides, box_dim, element_strides, CU_TENSOR_MAP_INTERLEAVE_NONE,
              CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_NONE,
              CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE),
          "cuTensorMapEncodeTiled(prepared W1 data, 64-row boxes)");
  return map;
}

inline CUtensorMap EncodeAdjacentW1DataTma(const TensorView& tensor) {
  uint64_t global_dim[3] = {128, 256, static_cast<uint64_t>(tensor.size(0))};
  uint64_t global_strides[2] = {128, 32768};
  uint32_t box_dim[3] = {128, 256, 1};
  uint32_t element_strides[3] = {1, 1, 1};
  CUtensorMap map;
  CheckCu(cuTensorMapEncodeTiled(
              &map, CU_TENSOR_MAP_DATA_TYPE_UINT8, 3, tensor.data_ptr(), global_dim,
              global_strides, box_dim, element_strides, CU_TENSOR_MAP_INTERLEAVE_NONE,
              CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_NONE,
              CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE),
          "cuTensorMapEncodeTiled(adjacent W1 data)");
  return map;
}

void RunCompleteRoutedImpl(
    TensorView hidden_states, TensorView hidden_states_scale, TensorView gemm1_weights,
    TensorView gemm1_weights_scale, TensorView gemm2_weights, TensorView gemm2_weights_scale,
    TensorView output1_scale_gate_scalar, TensorView output1_scale_scalar,
    TensorView output2_scale_scalar, TensorView sorted_token_ids, TensorView expert_ids,
    TensorView num_tokens_post_padded, TensorView topk_weights, TensorView out, TensorView topk_ids, TensorView cumsum_buffer,
    TensorView route_accumulator, TensorView route_experts,
    tvm::ffi::Optional<TensorView> owner_plan, tvm::ffi::Optional<TensorView> owner_count,
    tvm::ffi::Optional<TensorView> initial_out, tvm::ffi::Optional<TensorView> partial_workspace,
    tvm::ffi::Optional<TensorView> act_workspace, tvm::ffi::Optional<TensorView> sf_workspace,
    int64_t top_k, int64_t block_m, double routed_scaling_factor,
    tvm::ffi::Optional<TensorView> w1_scale_prepared, int64_t route_id,
    tvm::ffi::Optional<TensorView> w1_data_prepared,
    tvm::ffi::Optional<TensorView> w1_gate_up_data_prepared,
    tvm::ffi::Optional<TensorView> w1_gate_up_scale_prepared,
    tvm::ffi::Optional<TensorView> w2_scale_prepared,
    tvm::ffi::Optional<TensorView> w1_scale_prepared_interleaved,
    tvm::ffi::Optional<TensorView> merge_counters,
    tvm::ffi::Optional<TensorView> w2_data_prepared,
    bool accumulate,
    bool defer_finalize) {
  TVM_FFI_ICHECK(hidden_states.device().device_type == kDLCUDA)
      << "hidden_states must be a CUDA tensor";
  ffi::CUDADeviceGuard device_guard(hidden_states.device().device_id);
  const ProblemDims dims = CheckCompleteInputs(
      hidden_states, hidden_states_scale, gemm1_weights, gemm1_weights_scale,
      gemm2_weights, gemm2_weights_scale, output1_scale_gate_scalar, output1_scale_scalar,
      output2_scale_scalar, sorted_token_ids, expert_ids, num_tokens_post_padded,
      topk_weights, out, top_k, block_m, routed_scaling_factor);

  TVM_FFI_ICHECK(route_id >= 1 && route_id <= 15) << "invalid complete route id";
  const bool deferred = defer_finalize && DeferrableCompleteRoute(route_id);
  TVM_FFI_ICHECK(!defer_finalize || deferred) << "deferred finalize requires a deferrable complete route";
  TVM_FFI_ICHECK(dims.n == 1024 && dims.k == 6144 && gemm1_weights.size(0) == 256 &&
                 dims.top_k == 8 && dims.block_m == 8)
      << "complete route requires its selected geometry";
  const int device_id = hidden_states.device().device_id;
  CheckTensor(topk_ids, dl_int32, 2, true, "topk_ids", "int32");
  CheckSameDevice(topk_ids, device_id, "topk_ids");
  CheckShape2(topk_ids, dims.m, dims.top_k, "topk_ids");
  CheckTensor(cumsum_buffer, dl_int32, 1, true, "cumsum_buffer", "int32");
  CheckSameDevice(cumsum_buffer, device_id, "cumsum_buffer");
  TVM_FFI_ICHECK(cumsum_buffer.numel() >= gemm1_weights.size(0) + 2)
      << "cumsum_buffer must include all expert bins and the final prefix";
  CheckNoOverlap(out, topk_ids, "topk_ids");
  CheckNoOverlap(out, cumsum_buffer, "cumsum_buffer");
  const bool bf16_routes = route_id == 4 || route_id == 5 || route_id == 6 || route_id == 9 ||
      route_id == 10 || route_id == 11 || route_id == 12 || route_id == 13 ||
      route_id == 14 || route_id == 15;
  CheckTensor(route_accumulator, bf16_routes ? dl_bfloat16 : dl_float32, 2, true,
              "route_accumulator", bf16_routes ? "bfloat16" : "float32");
  CheckSameDevice(route_accumulator, device_id, "route_accumulator");
  CheckShape2(route_accumulator, dims.m * dims.top_k, dims.k, "route_accumulator");
  CheckNoOverlap(out, route_accumulator, "route_accumulator");
  CheckTensor(route_experts, dl_int32, 1, true, "route_experts", "int32");
  CheckSameDevice(route_experts, device_id, "route_experts");
  CheckShape1(route_experts, dims.m * dims.top_k, "route_experts");
  const int64_t capacity = expert_ids.numel();
  const int64_t blocks = dims.n / 256;
  const int64_t owner_capacity = (topk_ids.numel() + 31) / 32 + gemm1_weights.size(0);
  if (!deferred && (route_id == 1 || route_id == 2 || route_id == 6 || route_id == 7 || route_id == 8 || route_id == 9)) {
    TVM_FFI_ICHECK(initial_out.has_value()) << "complete route requires seed workspace";
    CheckTensor(initial_out.value(), dl_float32, 2, true, "initial_out", "float32");
    CheckSameDevice(initial_out.value(), device_id, "initial_out");
    CheckShape2(initial_out.value(), dims.m, dims.k, "initial_out");
    CheckNoOverlap(out, initial_out.value(), "initial_out");
  }
  const bool packed_scales = reinterpret_cast<uintptr_t>(hidden_states_scale.data_ptr()) % 4 == 0 &&
      reinterpret_cast<uintptr_t>(gemm1_weights_scale.data_ptr()) % 4 == 0 &&
      reinterpret_cast<uintptr_t>(gemm2_weights_scale.data_ptr()) % 4 == 0;
  // Route-9 fast chain (c416p up with in-kernel alignment, c405v5 persistent down, c402 r9 finalize): selected
  // when the caller owns the prepared W1 data panels, the interleaved W1 scale panels and the prepared W2 scale
  // panels. M=8 without them falls back to the c307/c338 chain; 9..kRoute9MaxTokens tokens require the fast chain.
  const bool route9_fast = owner_plan.has_value() && owner_count.has_value() && act_workspace.has_value() && sf_workspace.has_value() &&
        HasPreparedScale(w1_data_prepared, gemm1_weights,
                         gemm1_weights.size(0) * (dims.n / 128) * (dims.k / 256), 128) &&
        HasPreparedScale(w1_scale_prepared_interleaved, gemm1_weights_scale,
                         gemm1_weights.size(0) * (dims.n / 128) * (dims.k / 256), 16) &&
        HasPreparedScale(w2_scale_prepared, gemm2_weights_scale,
                         gemm1_weights.size(0) * (dims.k / 128) * blocks, 8);
  if (route_id == 1) {
    TVM_FFI_ICHECK(dims.m == 1 || dims.m == 8) << "split-K route requires one or eight tokens";
    TVM_FFI_ICHECK(partial_workspace.has_value()) << "missing split-K workspace";
    CheckTensor(partial_workspace.value(), dl_float32, 2, true, "partial_workspace", "float32");
    CheckSameDevice(partial_workspace.value(), device_id, "partial_workspace");
    CheckShape2(partial_workspace.value(), capacity * blocks, 8192, "partial_workspace");
  } else {
    TVM_FFI_ICHECK((route_id == 2 && dims.m == 8) || Route9TokenBand(route_id, dims.m, route9_fast) || ((route_id == 3 || route_id == 10 || route_id == 11) && dims.m == 128) ||
        ((route_id == 4 || route_id == 5 || route_id == 12 || route_id == 13 || route_id == 14 || route_id == 15) && dims.m == 512) ||
        (route_id == 6 && dims.m >= 128 && dims.m != 128 && dims.m != 512) ||
        (route_id == 7 && dims.m >= 8 && dims.m < 128 && dims.m != 8) ||
        (route_id == 8 && dims.m >= 2 && dims.m < 8))
        << "complete route id does not match token count";
    if (route_id == 14 || route_id == 15) {
      TVM_FFI_ICHECK(packed_scales && HasPreparedScale(w1_gate_up_scale_prepared, gemm1_weights_scale,
          gemm1_weights.size(0) * (dims.n / 256) * (dims.k / 256), 32))
          << "complete route requires adjacent gate/up W1 scales";
      CheckNoOverlap(out, w1_gate_up_scale_prepared.value(), "w1_gate_up_scale_prepared");
    } else {
    TVM_FFI_ICHECK(packed_scales && HasPreparedScale(w1_scale_prepared, gemm1_weights_scale,
        gemm1_weights.size(0) * (dims.n / 128) * (dims.k / 256), 16))
        << "complete route requires compatible prepared W1 scales";
    }
    TVM_FFI_ICHECK(act_workspace.has_value() && sf_workspace.has_value() &&
                   (route_id == 8 || (owner_plan.has_value() && owner_count.has_value())))
        << "missing complete route workspaces";
    if (route_id != 8) {
    CheckTensor(owner_plan.value(), dl_int32, 2, true, "owner_plan", "int32");
    CheckTensor(owner_count.value(), dl_int32, 1, true, "owner_count", "int32");
    }
    CheckTensor(act_workspace.value(), dl_uint8, 2, true, "act_workspace", "uint8");
    CheckTensor(sf_workspace.value(), dl_uint8, 2, true, "sf_workspace", "uint8");
    if (route_id != 8) {
    CheckSameDevice(owner_plan.value(), device_id, "owner_plan");
    CheckSameDevice(owner_count.value(), device_id, "owner_count");
    }
    CheckSameDevice(act_workspace.value(), device_id, "act_workspace");
    CheckSameDevice(sf_workspace.value(), device_id, "sf_workspace");
    if (route_id != 8) {
    CheckShape2(owner_plan.value(), owner_capacity, 3, "owner_plan");
    CheckShape1(owner_count.value(), 1, "owner_count");
    }
    CheckShape2(act_workspace.value(), capacity * blocks, 512, "act_workspace");
    CheckShape2(sf_workspace.value(), capacity * blocks, 1024, "sf_workspace");
  }
  const cudaStream_t stream = get_stream(hidden_states.device());
  // S7: the route-9 fast path (c402r9ns) and every c368-finalized route have a no-seed finalizer twin; with
  // accumulate == false they write the weighted route sum directly. Every other route seeds from `out`, so the
  // caller-visible semantics (result == seeded path on a zero output) are kept with one zero fill here.
